@@ -0,0 +1,102 @@
+package org.apache.streampipes.commons.net;
+
+import java.net.InetAddress;
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.net.UnknownHostException;
+import java.util.List;
+import java.util.stream.Collectors;
+
+/**
+ * Validates user-supplied endpoints to prevent Server-Side Request Forgery (SSRF) attacks.
+ * <p>
+ * The validator ensures that:
+ * <ul>
+ *   <li>the URL is well-formed,</li>
+ *   <li>only the http and https protocols are accepted, and</li>
+ *   <li>the host does not resolve to an internal, loopback, link-local,
+ *       site-local, multicast or otherwise non-routable address.</li>
+ * </ul>
+ */
+public final class EndpointValidator {
+
+    private EndpointValidator() {
+    }
+
+    /**
+     * Validates the given endpoint URL. Throws an {@link IllegalArgumentException}
+     * if the endpoint is invalid, uses a non-allowed protocol, or resolves to
+     * an internal address.
+     *
+     * @param endpoint the endpoint URL to validate
+     * @throws IllegalArgumentException if the endpoint is not safe to call
+     */
+    public static void validate(String endpoint) {
+        if (endpoint == null || endpoint.isBlank()) {
+            throw new IllegalArgumentException("Endpoint must not be empty");
+        }
+        URI uri;
+        try {
+            uri = new URI(endpoint);
+        } catch (URISyntaxException e) {
+            throw new IllegalArgumentException("Invalid endpoint URL: " + e.getMessage(), e);
+        }
+        String scheme = uri.getScheme();
+        if (scheme == null
+                || (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https"))) {
+            throw new IllegalArgumentException("Only http and https endpoints are allowed");
+        }
+        String host = uri.getHost();
+        if (host == null || host.isBlank()) {
+            throw new IllegalArgumentException("Endpoint must contain a valid host");
+        }
+        try {
+            InetAddress[] addresses = InetAddress.getAllByName(host);
+            for (InetAddress address : addresses) {
+                if (isInternal(address)) {
+                    throw new IllegalArgumentException(
+                            "Endpoint must not resolve to an internal or non-routable address");
+                }
+            }
+        } catch (UnknownHostException e) {
+            throw new IllegalArgumentException("Could not resolve endpoint host: " + e.getMessage(), e);
+        }
+    }
+
+    private static boolean isInternal(InetAddress address) {
+        if (address.isLoopbackAddress()
+                || address.isAnyLocalAddress()
+                || address.isLinkLocalAddress()
+                || address.isSiteLocalAddress()
+                || address.isMulticastAddress()) {
+            return true;
+        }
+        byte[] raw = address.getAddress();
+        if (raw.length == 4) {
+            int b0 = raw[0] & 0xff;
+            int b1 = raw[1] & 0xff;
+            if (b0 == 0 || b0 == 10 || b0 == 127) {
+                return true;
+            }
+            if (b0 == 169 && b1 == 254) {
+                return true; // 169.254.0.0/16 link-local
+            }
+            if (b0 == 172 && b1 >= 16 && b1 <= 31) {
+                return true; // 172.16.0.0/12 private
+            }
+            if (b0 == 192 && b1 == 168) {
+                return true; // 192.168.0.0/16 private
+            }
+            if (b0 == 100 && b1 >= 64 && b1 <= 127) {
+                return true; // 100.64.0.0/10 carrier-grade NAT
+            }
+            if (b0 >= 224) {
+                return true; // 224.0.0.0/4 multicast, 240.0.0.0/4 reserved
+            }
+        } else if (raw.length == 16) {
+            if ((raw[0] & 0xfe) == 0xfc) {
+                return true; // fc00::/7 unique local addresses
+            }
+            if (raw[0] == (byte) 0xfe && (raw[1] & 0xc0) == 0x80) {
+                return true; // fe80::/10 link-local
+            }
+        }
+        return false;
+    }
+}
