+module.exports.validateAppDefinition = (body) => {
+  if (!body || typeof body !== 'object') {
+    return false;
+  }
+
+  // Check overall definition size
+  const definitionStr = JSON.stringify(body);
+  if (definitionStr.length > MAX_APP_DEFINITION_SIZE) {
+    return false;
+  }
+
+  // Validate definition structure
+  if (body.definition) {
+    const definition = body.definition;
+    if (definition.pages && Array.isArray(definition.pages)) {
+      for (const page of definition.pages) {
+        if (page.queries && Array.isArray(page.queries)) {
+          for (const query of page.queries) {
+            if (query.query && query.query.length > MAX_QUERY_LENGTH) {
+              return false;
+            }
+          }
+        }
+      }
+    }
+  }
+
+  return true;
+};
